#!/usr/bin/env bash
#
# 03a — Real wheelhouse download for the CRAWLER deployable (requests).
#
# This is the small, fast, self-contained one: the crawler service needs only
# `requests` plus its transitive dependencies, and that is a complete cp310 /
# linux_x86_64 wheel set. Run this first to have a verified artifact early.
#
# Isolation rules honoured here:
#   * pip is NOT installed into the WSL global Python. A throwaway venv lives
#     under WORK_DIR (default /tmp/...) and is deleted afterwards.
#   * no sudo, no apt install, nothing is added to the WSL system.
#   * `pip download` only writes into the delivery directory.
#
# Output: ${WHEEL_DIR}/*.whl  and  ${OUT_DIR}/constraints-crawler.txt

set -euo pipefail
. "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/lib/common.sh"

require_cmd python3 find sort
ensure_dirs

# This script owns the CRAWLER wheelhouse. The Odoo wheelhouse is separate
# because Odoo pins requests==2.25.1 while the crawler needs 2.34.2.
WHEEL_DIR="${WHEEL_DIR_CRAWLER}"

VENV="${WORK_DIR}/venv-crawler"
[ -f "${CRAWLER_REQ}" ] || die "crawler requirements not found: ${CRAWLER_REQ}
  expected at <project>/lc_elc/server/ubuntu22.04/crawler/requirements.txt
  override with CRAWLER_REQ=/path/to/requirements.txt"

log "crawler requirements: ${CRAWLER_REQ}"
sed 's/^/    /' "${CRAWLER_REQ}"

run "copy crawler requirements into the bundle" \
    cp "${CRAWLER_REQ}" "${OUT_DIR}/crawler-requirements.txt"

# ---------------------------------------------------------------------------
# 1. Throwaway venv with a modern pip
# ---------------------------------------------------------------------------
if [ ! -x "${VENV}/bin/python" ]; then
    run "create throwaway venv (${VENV})" python3 -m venv "${VENV}"
fi
PY="${VENV}/bin/python"

run "upgrade pip/setuptools/wheel inside the venv (not global)" \
    "${PY}" -m pip install --quiet --upgrade pip setuptools wheel

pip_ver="$("${PY}" -m pip --version)"
log "venv pip: ${pip_ver}"

# ---------------------------------------------------------------------------
# 2. Download every wheel for this platform
# ---------------------------------------------------------------------------
before=$(find "${WHEEL_DIR}" -maxdepth 1 -name '*.whl' 2>/dev/null | wc -l | tr -d ' ')

run "pip download -r crawler requirements -d ${WHEEL_DIR}" \
    "${PY}" -m pip download -r "${OUT_DIR}/crawler-requirements.txt" -d "${WHEEL_DIR}"

after=$(find "${WHEEL_DIR}" -maxdepth 1 -name '*.whl' 2>/dev/null | wc -l | tr -d ' ')
log "wheels: ${before} -> ${after}"

# ---------------------------------------------------------------------------
# 3. AUTHORITATIVE offline check: resolve from the wheelhouse with no index
# ---------------------------------------------------------------------------
run "offline resolution check (--no-index, crawler requirements)" \
    "${PY}" -m pip install --no-index --find-links "${WHEEL_DIR}" \
        -r "${OUT_DIR}/crawler-requirements.txt" \
        --dry-run --ignore-installed \
        --report "${OUT_DIR}/pip-resolve-crawler.json"

run "write constraints-crawler.txt" \
    "${PY}" - "${OUT_DIR}/pip-resolve-crawler.json" \
        "${OUT_DIR}/constraints-crawler.txt" <<'PY'
import json, sys

src, dest = sys.argv[1], sys.argv[2]
with open(src, encoding="utf-8") as fh:
    data = json.load(fh)

pins = {}
for item in data.get("install", []):
    meta = item.get("metadata", {})
    if meta.get("name") and meta.get("version"):
        pins[meta["name"]] = meta["version"]

with open(dest, "w", encoding="utf-8") as fh:
    fh.write("# Exact versions present in wheelhouse/ for the crawler service.\n")
    fh.write("# Generated by 03a_requests_wheelhouse.sh from an OFFLINE resolution.\n")
    for name in sorted(pins, key=str.lower):
        fh.write(f"{name}=={pins[name]}\n")

for name in sorted(pins, key=str.lower):
    print(f"    {name}=={pins[name]}")
print(f"{len(pins)} distributions pinned -> {dest}")
PY

# ---------------------------------------------------------------------------
# 4. Report what is actually on disk
# ---------------------------------------------------------------------------
echo
echo "--- wheelhouse contents ---"
find "${WHEEL_DIR}" -maxdepth 1 -name '*.whl' -printf '    %f\n' | sort | sed 's/^/  /'
echo
printf 'wheel count : %s\n' "$(find "${WHEEL_DIR}" -maxdepth 1 -name '*.whl' | wc -l | tr -d ' ')"
printf 'sdists      : %s\n' "$(find "${WHEEL_DIR}" -maxdepth 1 \( -name '*.tar.gz' -o -name '*.zip' \) | wc -l | tr -d ' ')"
printf 'total size  : %s\n' "$(du -sh "${WHEEL_DIR}" | cut -f1)"

sdist_count=$(find "${WHEEL_DIR}" -maxdepth 1 \( -name '*.tar.gz' -o -name '*.zip' \) | wc -l | tr -d ' ')
if [ "${sdist_count}" -gt 0 ]; then
    warn "${sdist_count} sdist(s) present — those would need compiling on the target."
else
    ok "no sdists: the crawler wheelhouse is pure-wheel and fully offline-installable"
fi

case "${VENV}" in
    "${WORK_DIR}"/*) rm -rf -- "${VENV}" ;;
    *) warn "not removing unexpected venv path: ${VENV}" ;;
esac
ok "done; global Python untouched (pip was only ever used inside the venv)"
